import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { chatAPI, documentsAPI } from "../services/api";

const Chat = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [docStatus, setDocStatus] = useState(null);
  const messagesEndRef = useRef(null);

  const statusLabel = docStatus?.has_documents
    ? `${docStatus.files_count} document${
        docStatus.files_count !== 1 ? "s" : ""
      } indexed`
    : docStatus?.folder_count > 0
    ? `${docStatus.folder_count} file${
        docStatus.folder_count !== 1 ? "s" : ""
      } found`
    : docStatus
    ? "No documents yet"
    : "Checking documents...";
  const statusTone = docStatus?.has_documents
    ? "bg-emerald-50 text-emerald-700 border-emerald-200"
    : docStatus?.folder_count > 0
    ? "bg-amber-50 text-amber-800 border-amber-200"
    : "bg-slate-50 text-slate-600 border-slate-200";
  const statusIcon = docStatus?.has_documents
    ? "✅"
    : docStatus?.folder_count > 0
    ? "⚠️"
    : "📂";
  const canReload =
    docStatus && !docStatus.has_documents && docStatus.folder_count > 0;
  const userInitial = user?.username?.[0]?.toUpperCase() || "U";

  useEffect(() => {
    loadDocumentStatus();
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const loadDocumentStatus = async () => {
    try {
      const statusResponse = await documentsAPI.status();
      console.log("📊 Document Status:", statusResponse.data);
      setDocStatus(statusResponse.data);
    } catch (error) {
      console.error("❌ Error loading document status:", error);
      // Set default status on error
      setDocStatus({
        has_documents: false,
        folder_count: 0,
        files_count: 0,
      });
    }
  };

  const handleReloadDocuments = async () => {
    try {
      setLoading(true);
      await documentsAPI.reload(false);
      await loadDocumentStatus();
      const successMsg = {
        id: Date.now(),
        type: "system",
        content: "✅ Documents reloaded successfully!",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, successMsg]);
    } catch (error) {
      const errorMsg = {
        id: Date.now(),
        type: "error",
        content:
          error.response?.data?.detail ||
          "Failed to reload documents. Please try again.",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMsg]);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const handleSend = async (e) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMessage = {
      id: Date.now(),
      type: "user",
      content: input.trim(),
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    try {
      const response = await chatAPI.query({ query: input.trim() });
      const botMessage = {
        id: Date.now() + 1,
        type: "bot",
        content: response.data.answer,
        citations: response.data.citations,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botMessage]);
    } catch (error) {
      const errorMessage = {
        id: Date.now() + 1,
        type: "error",
        content:
          error.response?.data?.detail ||
          "Failed to get response. Please try again.",
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMessage]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend(e);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gradient-to-br from-slate-50 via-white to-slate-100">
      {/* Header */}
      <header className="bg-white/80 border-b border-slate-200 shadow-sm backdrop-blur sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-wrap gap-4 justify-between items-center py-4">
            <div className="flex items-center space-x-4">
              <div className="w-11 h-11 bg-gradient-to-br from-blue-600 to-blue-700 rounded-xl flex items-center justify-center shadow-md">
                <svg
                  className="w-6 h-6 text-white"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
                  />
                </svg>
              </div>
              <div className="space-y-1">
                <h1 className="text-xl font-semibold text-slate-900 tracking-tight">
                  Sahakari Bot
                </h1>
                <div className="flex items-center gap-2 text-xs text-slate-500">
                  <span
                    className={`inline-flex items-center gap-1.5 px-2.5 py-1 border rounded-full ${statusTone}`}
                  >
                    <span>{statusIcon}</span>
                    {statusLabel}
                  </span>
                  <span className="hidden sm:inline">
                    Document intelligence workspace
                  </span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {canReload && (
                <button
                  onClick={handleReloadDocuments}
                  disabled={loading}
                  className="px-3 py-1.5 text-xs font-medium text-blue-700 bg-blue-50 rounded-lg hover:bg-blue-100 focus:outline-none focus:ring-2 focus:ring-blue-500 transition disabled:opacity-50"
                  title="Reload documents from folder"
                >
                  🔄 Reload
                </button>
              )}
              <div className="hidden sm:flex items-center gap-2 bg-white border border-slate-200 rounded-full px-3 py-1.5 shadow-sm">
                <span className="w-7 h-7 rounded-full bg-slate-900 text-white text-xs flex items-center justify-center">
                  {userInitial}
                </span>
                <span className="text-sm text-slate-700">{user?.username}</span>
              </div>
              <button
                onClick={handleLogout}
                className="px-4 py-2 text-sm font-medium text-white bg-gradient-to-r from-blue-600 to-blue-700 rounded-lg hover:from-blue-700 hover:to-blue-800 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition shadow-sm"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto px-4 sm:px-6 py-6">
        <div className="max-w-5xl w-full mx-auto">
          {messages.length === 0 ? (
            <div className="text-center mt-10 sm:mt-16">
              <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-blue-100 to-blue-200 rounded-2xl mb-6 shadow-lg">
                <svg
                  className="w-10 h-10 text-blue-600"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z"
                  />
                </svg>
              </div>
              <h2 className="text-3xl font-semibold text-slate-900 mb-3">
                Welcome to Sahakari Bot!
              </h2>
              <p className="text-slate-600 mb-8 max-w-xl mx-auto">
                Ask questions about cybersecurity compliance, regulations, and
                risk management based on your document library.
              </p>
              {!docStatus?.has_documents && (
                <div className="max-w-xl mx-auto bg-amber-50 border border-amber-200 rounded-2xl p-4 mb-6 text-left shadow-sm">
                  {docStatus?.folder_count > 0 ? (
                    <div>
                      <p className="text-sm text-amber-800 mb-2">
                        ⚠️ Found {docStatus.folder_count} file
                        {docStatus.folder_count !== 1 ? "s" : ""} in your
                        folder, but they are not processed yet.
                      </p>
                      <button
                        onClick={handleReloadDocuments}
                        disabled={loading}
                        className="text-xs px-3 py-1.5 bg-amber-100 hover:bg-amber-200 text-amber-900 rounded-full font-medium transition disabled:opacity-50"
                      >
                        {loading ? "Processing..." : "🔄 Process Documents Now"}
                      </button>
                    </div>
                  ) : (
                    <p className="text-sm text-amber-800">
                      ⚠️ No documents found. Add files to{" "}
                      <code className="bg-amber-100 px-1 rounded">
                        data/documents/
                      </code>{" "}
                      folder and restart the server or click reload.
                    </p>
                  )}
                </div>
              )}
              <div className="grid gap-4 sm:grid-cols-2 max-w-3xl mx-auto">
                <div className="text-left bg-white rounded-2xl p-6 shadow-lg border border-slate-200">
                  <p className="text-sm font-semibold text-slate-700 mb-4 flex items-center">
                    <svg
                      className="w-5 h-5 text-blue-600 mr-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M13 10V3L4 14h7v7l9-11h-7z"
                      />
                    </svg>
                    Try asking
                  </p>
                  <ul className="space-y-3 text-sm text-slate-600">
                    <li className="flex items-start group">
                      <span className="text-blue-600 mr-3 mt-1">•</span>
                      <span className="group-hover:text-slate-900 transition">
                        What are the password requirements?
                      </span>
                    </li>
                    <li className="flex items-start group">
                      <span className="text-blue-600 mr-3 mt-1">•</span>
                      <span className="group-hover:text-slate-900 transition">
                        How should we handle insider threats?
                      </span>
                    </li>
                    <li className="flex items-start group">
                      <span className="text-blue-600 mr-3 mt-1">•</span>
                      <span className="group-hover:text-slate-900 transition">
                        What are the data protection guidelines?
                      </span>
                    </li>
                  </ul>
                </div>
                <div className="text-left bg-white rounded-2xl p-6 shadow-lg border border-slate-200">
                  <p className="text-sm font-semibold text-slate-700 mb-4 flex items-center">
                    <svg
                      className="w-5 h-5 text-emerald-600 mr-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M5 13l4 4L19 7"
                      />
                    </svg>
                    Best practices
                  </p>
                  <ul className="space-y-3 text-sm text-slate-600">
                    <li className="flex items-start">
                      <span className="text-emerald-600 mr-3 mt-1">•</span>
                      <span>Reference specific policies or clauses.</span>
                    </li>
                    <li className="flex items-start">
                      <span className="text-emerald-600 mr-3 mt-1">•</span>
                      <span>Ask follow-ups to refine scope.</span>
                    </li>
                    <li className="flex items-start">
                      <span className="text-emerald-600 mr-3 mt-1">•</span>
                      <span>Verify citations for audit readiness.</span>
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          ) : (
            <div className="space-y-5 pb-4">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${
                    msg.type === "user" ? "justify-end" : "justify-start"
                  }`}
                >
                  <div
                    className={`max-w-3xl px-4 py-3 rounded-2xl shadow-sm ${
                      msg.type === "user"
                        ? "bg-gradient-to-r from-blue-600 to-blue-700 text-white"
                        : msg.type === "error"
                        ? "bg-red-50 text-red-800 border border-red-200"
                        : "bg-white text-slate-800 border border-slate-200"
                    }`}
                  >
                    <div className="text-xs uppercase tracking-wide opacity-60 mb-2">
                      {msg.type === "user"
                        ? "You"
                        : msg.type === "error"
                        ? "System"
                        : "Sahakari Bot"}
                    </div>
                    <p className="whitespace-pre-wrap leading-relaxed text-sm sm:text-base">
                      {msg.content}
                    </p>
                    {msg.citations && msg.citations.length > 0 && (
                      <div className="mt-4 pt-3 border-t border-slate-200 border-opacity-40">
                        <p className="text-xs font-semibold text-slate-600 mb-2 flex items-center">
                          <svg
                            className="w-4 h-4 mr-1"
                            fill="none"
                            stroke="currentColor"
                            viewBox="0 0 24 24"
                          >
                            <path
                              strokeLinecap="round"
                              strokeLinejoin="round"
                              strokeWidth={2}
                              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                            />
                          </svg>
                          Sources ({msg.citations.length}):
                        </p>
                        <div className="space-y-1.5">
                          {msg.citations.map((citation, idx) => (
                            <div
                              key={idx}
                              className="text-xs text-slate-500 bg-slate-50 rounded-lg px-2 py-1.5"
                            >
                              <span className="font-medium">
                                📄 {citation.source}
                              </span>
                              {citation.page && (
                                <span className="text-slate-400">
                                  {" "}
                                  • Page {citation.page}
                                </span>
                              )}
                              {citation.relevance_score && (
                                <span className="text-slate-400">
                                  {" "}
                                  • Relevance:{" "}
                                  {(citation.relevance_score * 100).toFixed(0)}%
                                </span>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                    <p className="text-xs mt-2 opacity-70">
                      {new Date(msg.timestamp).toLocaleTimeString()}
                    </p>
                  </div>
                </div>
              ))}
              {loading && (
                <div className="flex justify-start">
                  <div className="bg-white px-4 py-3 rounded-2xl shadow-sm border border-gray-200">
                    <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-blue-600 rounded-full animate-bounce"></div>
                      <div
                        className="w-2 h-2 bg-blue-600 rounded-full animate-bounce"
                        style={{ animationDelay: "0.1s" }}
                      ></div>
                      <div
                        className="w-2 h-2 bg-blue-600 rounded-full animate-bounce"
                        style={{ animationDelay: "0.2s" }}
                      ></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>
          )}
        </div>
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 shadow-lg">
        <div className="max-w-5xl mx-auto p-4">
          <div className="flex items-center justify-between text-xs text-slate-500 mb-2 px-1">
            <span>Ask anything about your compliance knowledge base</span>
            <span className="hidden sm:inline">Press Enter to send</span>
          </div>
          <form onSubmit={handleSend} className="flex space-x-3">
            <textarea
              rows={1}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="Ask about compliance, regulations, or risk management..."
              className="flex-1 px-4 py-3 border border-slate-300 rounded-2xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition shadow-sm resize-none"
              disabled={loading}
            />
            <button
              type="submit"
              disabled={loading || !input.trim()}
              className="px-6 py-3 bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-2xl hover:from-blue-700 hover:to-blue-800 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition shadow-md font-medium"
            >
              {loading ? (
                <svg
                  className="w-5 h-5 animate-spin"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  ></path>
                </svg>
              ) : (
                "Send"
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Chat;
